function getDealSize(amount) {
  if (!amount) return "unknown";
  if (amount < 5000) return "small";
  if (amount < 20000) return "medium";
  return "large";
}

// Helper: normalize customer segment
function getCustomerSegment(type) {
  if (!type) return "unknown";
  const t = type.toLowerCase();
  if (t.includes("enterprise")) return "enterprise";
  if (t.includes("smb")) return "smb";
  return "mid-market";
}

// Normalized output
const normalized = {
  quote_id: $('Quote Trigger (Webhook)').first().json.body.quoteId || null,
  opportunity_id: $('Fetch Opportunity Details').first().json.Id || null,
  account_id: $input.first().json.Id || null,

  // Core deal data
  deal_amount: $('Fetch Opportunity Details').first().json.Amount || 0,
  close_date: $('Fetch Opportunity Details').first().json.CloseDate || null,
  stage: $('Fetch Opportunity Details').first().json.StageName || "unknown",

  // Derived fields
  deal_size: getDealSize($('Fetch Opportunity Details').first().json.Amount),
  customer_segment: getCustomerSegment($input.first().json.Type),

  // Contextual enrichment
  industry: $input.first().json.Industry || "unknown",
  region: $input.first().json.BillingCity || "unknown", // optional future use

  // Metadata for AI
  timestamp: new Date().toISOString()
};

return [{ json: normalized }];

const current = $items("Normalize Deal Context")[0].json;
const history = items.map(item => item.json);

// Normalize helper
const normalize = (val) => (val || "").toString().toLowerCase().trim();

function score(deal) {
  let score = 0;
  if (normalize(deal.DealSize) === normalize(current.deal_size)) score += 3;
  if (normalize(deal.Segment) === normalize(current.customer_segment)) score += 2;
  if (normalize(deal.Industry) === normalize(current.industry)) score += 1;
  return score;
}

const ranked = history
  .map(d => ({ ...d, score: score(d) }))
  .filter(d => d.score >= 3) // threshold
  .sort((a, b) => b.score - a.score);

return ranked.map(d => ({ json: d }));

const deals = items.map(item => item.json);

// Separate won/lost deals
const wonDeals = deals.filter(d => (d.Outcome || "").toLowerCase() === "won");
const lostDeals = deals.filter(d => (d.Outcome || "").toLowerCase() === "lost");

// Helper function
const avg = (arr, field) => {
  if (arr.length === 0) return 0;
  return arr.reduce((sum, d) => sum + Number(d[field] || 0), 0) / arr.length;
};

// Calculations
const avgWonDiscount = avg(wonDeals, "DiscountGiven");
const avgLostDiscount = avg(lostDeals, "DiscountGiven");

const winRate = deals.length > 0 ? (wonDeals.length / deals.length) : 0;

// Safe pricing logic
let recommendedDiscount = avgWonDiscount;

// Adjust if losing deals had higher discounts (bad sign)
if (avgLostDiscount > avgWonDiscount) {
  recommendedDiscount = (avgWonDiscount + avgLostDiscount) / 2;
}

// Define safe range
const minDiscount = Math.max(0, avgWonDiscount - 2);
const maxDiscount = avgLostDiscount > 0 ? avgLostDiscount : avgWonDiscount + 5;

// Output
const result = {
  total_deals_considered: deals.length,
  win_rate: Number(winRate.toFixed(2)),

  avg_won_discount: Number(avgWonDiscount.toFixed(2)),
  avg_lost_discount: Number(avgLostDiscount.toFixed(2)),

  recommended_discount: Number(recommendedDiscount.toFixed(2)),

  discount_range: {
    min: Number(minDiscount.toFixed(2)),
    max: Number(maxDiscount.toFixed(2))
  }
};

return [{ json: result }];

